// URL prefix per language. `/zh-hans/blog/<slug>`, `/zh-hant/blog/<slug>`.
export const ARTICLE_LANG_PREFIX: Record<ArticleLang, string> = {
  'zh-Hans': contentLocalePrefix('zh-Hans'),
  'zh-Hant': contentLocalePrefix('zh-Hant'),
};

